-- ============================================
-- LUMA — Thème 8 (Fantasy) : 3 scénarios COURTS x4
-- ============================================


update scenarios set content = '{"characters": {"guard": "le garde"}, "start_node": "n1", "nodes": {"n1": {"speaker": "guard", "text": "Halt! State your business at the village gate, traveler.", "text_fr": "Halte ! Déclarez vos intentions à la porte du village, voyageur.", "choices": [{"text": "I seek the path to the enchanted forest, good sir.", "text_fr": "Je cherche le chemin vers la forêt enchantée, bon sire.", "next": "n2"}, {"text": "I mean no harm, I''m simply passing through toward the forest.", "text_fr": "Je ne veux aucun mal, je fais juste passer vers la forêt.", "next": "n2b"}]}, "n2": {"speaker": "guard", "text": "The enchanted forest? That''s dangerous ground for most travelers.", "text_fr": "La forêt enchantée ? C''est un terrain dangereux pour la plupart des voyageurs.", "choices": [{"text": "I''ve faced danger before. I must go regardless.", "text_fr": "J''ai déjà fait face au danger. Je dois y aller malgré tout.", "next": "n3"}, {"text": "Is there a safer path I should be aware of?", "text_fr": "Il y a un chemin plus sûr dont je devrais être conscient ?", "next": "n3b"}]}, "n2b": {"speaker": "guard", "text": "Passing through, are you? The forest isn''t a place for the unprepared.", "text_fr": "Vous passez, hein ? La forêt n''est pas un endroit pour les non préparés.", "choices": [{"text": "I appreciate the warning, but I''m ready for what lies ahead.", "text_fr": "J''apprécie l''avertissement, mais je suis prêt pour ce qui m''attend.", "next": "n3"}]}, "n3": {"speaker": "guard", "text": "Very well. Follow the northern road past the old mill, then head east at the fork.", "text_fr": "Très bien. Suivez la route du nord après le vieux moulin, puis prenez à l''est à la bifurcation.", "choices": [{"text": "Thank you for the directions, guardsman.", "text_fr": "Merci pour les indications, garde.", "next": "n4"}]}, "n3b": {"speaker": "guard", "text": "There''s a longer route around the marshes, safer but slower.", "text_fr": "Il y a une route plus longue autour des marais, plus sûre mais plus lente.", "choices": [{"text": "I''ll take my chances with the direct path instead, thank you.", "text_fr": "Je vais tenter ma chance avec le chemin direct plutôt, merci.", "next": "n4"}, {"text": "Actually, the safer route sounds wise. Please, tell me more.", "text_fr": "En fait, la route plus sûre semble sage. Dites-m''en plus, s''il vous plaît.", "next": "n4b"}]}, "n4": {"speaker": "guard", "text": "Watch for the will-o''-the-wisps near dusk. They lead travelers astray.", "text_fr": "Méfiez-vous des feux follets au crépuscule. Ils égarent les voyageurs.", "choices": [{"text": "I''ll heed your warning. Farewell.", "text_fr": "Je vais tenir compte de votre avertissement. Adieu.", "next": "end_directed"}]}, "n4b": {"speaker": "guard", "text": "Wise choice. Follow the marsh path west, it adds a day but avoids the worst dangers.", "text_fr": "Sage choix. Suivez le chemin des marais à l''ouest, ça ajoute un jour mais évite les pires dangers.", "choices": [{"text": "I''m grateful for your guidance, guardsman.", "text_fr": "Je vous suis reconnaissant pour vos conseils, garde.", "next": "end_directed"}]}, "end_directed": {"speaker": "guard", "text": "Safe travels, stranger. May fortune favor your journey.", "text_fr": "Bon voyage, étranger. Que la fortune favorise votre périple.", "end": true, "ending_label": "Chemin vers la forêt indiqué 🗺️"}}}'::jsonb, is_playable = true
where title = 'Demander son chemin à un garde du village'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));


update scenarios set content = '{"characters": {"merchant": "le marchand ambulant"}, "start_node": "n1", "nodes": {"n1": {"speaker": "merchant", "text": "Ah, a traveler! Come, see my wares — potions, charms, and more!", "text_fr": "Ah, un voyageur ! Venez, voyez mes marchandises — potions, amulettes, et plus encore !", "choices": [{"text": "What potions do you have for protection against dark creatures?", "text_fr": "Quelles potions avez-vous pour se protéger des créatures obscures ?", "next": "n2"}, {"text": "I''m looking for something to help me see in the dark forest.", "text_fr": "Je cherche quelque chose pour m''aider à voir dans la forêt sombre.", "next": "n2b"}]}, "n2": {"speaker": "merchant", "text": "Ah, this Elixir of Warding! Only 30 gold pieces, keeps most shadow beasts at bay.", "text_fr": "Ah, cet Élixir de Protection ! Seulement 30 pièces d''or, tient la plupart des bêtes de l''ombre à distance.", "choices": [{"text": "30 gold seems steep. Would you accept 20?", "text_fr": "30 pièces d''or ça semble cher. Vous accepteriez 20 ?", "next": "n3"}, {"text": "I''ll take it, that sounds essential for my journey.", "text_fr": "Je le prends, ça semble essentiel pour mon voyage.", "next": "n3b"}]}, "n2b": {"speaker": "merchant", "text": "A Lantern of Everlight, never needs oil! Yours for 25 gold pieces.", "text_fr": "Une Lanterne de Lumière Éternelle, jamais besoin d''huile ! À vous pour 25 pièces d''or.", "choices": [{"text": "That''s a fair price, I''ll take it.", "text_fr": "C''est un prix juste, je le prends.", "next": "n3b"}, {"text": "Could you do 18 gold instead? I don''t have much coin.", "text_fr": "Vous pourriez faire 18 pièces d''or plutôt ? Je n''ai pas beaucoup d''argent.", "next": "n3"}]}, "n3": {"speaker": "merchant", "text": "(Strokes beard) You drive a hard bargain... 25 gold, final offer.", "text_fr": "(Se caresse la barbe) Vous négociez dur... 25 pièces d''or, dernière offre.", "choices": [{"text": "Deal! Here''s your gold.", "text_fr": "Marché conclu ! Voici votre or.", "next": "n4"}]}, "n3b": {"speaker": "merchant", "text": "Excellent choice! A wise traveler prepares well.", "text_fr": "Excellent choix ! Un voyageur sage se prépare bien.", "choices": [{"text": "Thank you, safe travels to you as well.", "text_fr": "Merci, bon voyage à vous aussi.", "next": "n4"}]}, "n4": {"speaker": "merchant", "text": "May this serve you well on your journey, traveler.", "text_fr": "Que ceci vous serve bien dans votre voyage, voyageur.", "choices": [{"text": "I''m grateful for your wares. Farewell, merchant.", "text_fr": "Je suis reconnaissant pour vos marchandises. Adieu, marchand.", "next": "end_bought"}]}, "end_bought": {"speaker": "merchant", "text": "Farewell! Return if you need more supplies!", "text_fr": "Adieu ! Revenez si vous avez besoin d''autres provisions !", "end": true, "ending_label": "Objet essentiel négocié avec le marchand 🧙‍♂️💰"}}}'::jsonb, is_playable = true
where title = 'Négocier avec un marchand ambulant'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));
